    "workers.info.heatmap":    "Қаторлар — бригадирлар, устунлар — кунлар. Ҳар бир катакча — ўша куни рўйхатдагиларнинг неча фоизи ишга чиққани (келган ÷ рўйхатдаги). Яшил — деярли ҳамма келган (≥90%), сариқ — 75–90%, қизил — 75% дан кам. Катакча устига курсорни олиб борсангиз аниқ сонлар чиқади; бўш катакча — кун тасдиқланмаган.",
